2: 
3: /// The largest sum of any CONTIGUOUS non-empty run of values.
4: ///
5: /// Handles negatives: a run may dip below zero and still be the best overall.
6: pub fn max_run(values: &[i64]) -> i64 {
7:     let mut best = values[0];
8:     let mut here = values[0];
9:     for &v in &values[1..] {
10:         here = here.max(v);
11:         best = best.max(here);
12:     }
13:     best
14: }

