1: //! Generic grid A* pathfinding primitives.
2: //!
3: //! [`astar_bool_grid`] takes a `&[bool]` blocking mask and finds a
4: //! 4-connected path between two cells. Manhattan heuristic, uniform cost
5: //! per step. Returned path excludes the start cell and includes the goal,
6: //! in `(col, row)` pairs. Empty `Vec` when start == goal. `None` when
7: //! unreachable.
8: //!
9: //! Game-side grid pathfinders (tile floors with per-tile blocking rules,
10: //! ACL doors, etc.) live in `void_sim::pathfind` and reuse this
11: //! primitive when the tile source can be flattened to a bool grid.
12: 
13: use std::cmp::Reverse;
14: use std::collections::{BinaryHeap, HashMap, HashSet};
15: 
16: /// A* open set: a min-heap keyed on `(f_score, g_score, (col, row))`.
17: /// `Reverse` turns `BinaryHeap`'s max-heap into the min-heap A* wants,
18: /// and `g_score` breaks f-score ties toward the deeper node.
19: type OpenSet = BinaryHeap<Reverse<(u32, u32, (i32, i32))>>;
20: 
21: /// A caller-supplied tile-blocking source. Lets `astar_grid` run over
22: /// any game-side tile representation (station floor, ship exterior,
23: /// etc.) without engine dragging in game types. Out-of-bounds cells
24: /// should return `true` from `blocks`.
25: pub trait TileSource {
26:     /// Grid dimensions in `(width, height)` tile counts.
27:     fn dims(&self) -> (u32, u32);
28:     /// True if `(c, r)` is impassable. Return `true` for out-of-bounds.
29:     fn blocks(&self, c: i32, r: i32) -> bool;
30: }
31: 
32: /// A* on any [`TileSource`]. Same rules as [`astar_bool_grid`] —
33: /// 4-connected, Manhattan heuristic, uniform cost, excludes start,
34: /// includes goal. `extra_blocked` layers extra impassable cells on top
35: /// (used to reject e.g. occupied dock pads that the tile source itself
36: /// would call walkable).
37: pub fn astar_tile_grid<T: TileSource>(
38:     src: &T,
39:     start: (i32, i32),
40:     goal:  (i32, i32),
41:     extra_blocked: &HashSet<(i32, i32)>,
42: ) -> Option<Vec<(u16, u16)>> {
43:     if start == goal { return Some(Vec::new()); }
44:     if src.blocks(goal.0, goal.1) { return None; }
45:     let (w, h) = src.dims();
46:     let heur = |p: (i32, i32)| -> u32 {
47:         (p.0 - goal.0).unsigned_abs() + (p.1 - goal.1).unsigned_abs()
48:     };
49:     let mut open: OpenSet = BinaryHeap::new();
50:     let mut g_score: HashMap<(i32, i32), u32> = HashMap::new();
51:     let mut came_from: HashMap<(i32, i32), (i32, i32)> = HashMap::new();
52:     let mut closed: HashSet<(i32, i32)> = HashSet::new();
53:     open.push(Reverse((heur(start), 0, start)));
54:     g_score.insert(start, 0);
55:     let cap = (w as usize).saturating_mul(h as usize).max(1);
56:     let mut expanded = 0usize;
57:     while let Some(Reverse((_f, g, cur))) = open.pop() {
58:         if cur == goal { return Some(reconstruct(&came_from, cur)); }
59:         if !closed.insert(cur) { continue; }
60:         expanded += 1;
61:         if expanded > cap { return None; }
62:         for (dx, dy) in [(0i32, 1i32), (0, -1), (1, 0), (-1, 0)] {
63:             let nb = (cur.0 + dx, cur.1 + dy);
64:             if src.blocks(nb.0, nb.1) { continue; }
65:             if extra_blocked.contains(&nb) { continue; }
66:             if closed.contains(&nb) { continue; }
67:             let tentative = g + 1;
68:             let better = g_score.get(&nb).is_none_or(|&old| tentative < old);
69:             if !better { continue; }
70:             g_score.insert(nb, tentative);
71:             came_from.insert(nb, cur);
72:             open.push(Reverse((tentative + heur(nb), tentative, nb)));
73:         }
74:     }
75:     None
76: }
77: 
78: /// A* over a caller-supplied bool grid (`blocked[row*width + col]`).
79: /// 4-connected, Manhattan heuristic. Returned path excludes the start
80: /// cell and includes the goal, in `(col, row)` pairs.
81: pub fn astar_bool_grid(
82:     width:   u32,
83:     height:  u32,
84:     blocked: &[bool],
85:     start:   (i32, i32),
86:     goal:    (i32, i32),
87: ) -> Option<Vec<(u16, u16)>> {
88:     if start == goal { return Some(Vec::new()); }
89:     let w = width as i32;
90:     let h = height as i32;
91:     let idx = |c: i32, r: i32| -> Option<usize> {
92:         if c < 0 || r < 0 || c >= w || r >= h { return None; }
93:         Some((r as usize) * (width as usize) + (c as usize))
94:     };
95:     let blocks = |c: i32, r: i32| -> bool {
96:         match idx(c, r) {
97:             Some(i) => blocked.get(i).copied().unwrap_or(true),
98:             None    => true,
99:         }
100:     };
101:     if blocks(goal.0, goal.1) { return None; }
102:     let heur = |p: (i32, i32)| -> u32 {
103:         (p.0 - goal.0).unsigned_abs() + (p.1 - goal.1).unsigned_abs()
104:     };
105:     let mut open: OpenSet = BinaryHeap::new();
106:     let mut g_score: HashMap<(i32, i32), u32> = HashMap::new();
107:     let mut came_from: HashMap<(i32, i32), (i32, i32)> = HashMap::new();
108:     let mut closed: HashSet<(i32, i32)> = HashSet::new();
109:     open.push(Reverse((heur(start), 0, start)));
110:     g_score.insert(start, 0);
111:     let cap = (w as usize).saturating_mul(h as usize).max(1);
112:     let mut expanded = 0usize;
113:     while let Some(Reverse((_f, g, cur))) = open.pop() {
114:         if cur == goal { return Some(reconstruct(&came_from, cur)); }
115:         if !closed.insert(cur) { continue; }
116:         expanded += 1;
117:         if expanded > cap { return None; }
118:         for (dx, dy) in [(0i32, 1i32), (0, -1), (1, 0), (-1, 0)] {
119:             let nb = (cur.0 + dx, cur.1 + dy);
120:             if blocks(nb.0, nb.1) { continue; }
121:             if closed.contains(&nb) { continue; }
122:             let tentative = g + 1;
123:             let better = g_score.get(&nb).is_none_or(|&old| tentative < old);
124:             if !better { continue; }
125:             g_score.insert(nb, tentative);
126:             came_from.insert(nb, cur);
127:             open.push(Reverse((tentative + heur(nb), tentative, nb)));
128:         }
129:     }
130:     None
131: }
132: 
133: fn reconstruct(
134:     came_from: &HashMap<(i32, i32), (i32, i32)>,
135:     mut cur: (i32, i32),
136: ) -> Vec<(u16, u16)> {
137:     let mut path = Vec::new();
138:     while let Some(&prev) = came_from.get(&cur) {
139:         path.push((cur.0 as u16, cur.1 as u16));
140:         cur = prev;
141:     }
142:     path.reverse();
143:     path
144: }

