fn reconstruct(
    came_from: &HashMap<(i32, i32), (i32, i32)>,
    mut cur: (i32, i32),
) -> Vec<(u16, u16)> {
    let mut path = Vec::new();
    while let Some(&prev) = came_from.get(&cur) {
        path.push((cur.0 as u16, cur.1 as u16));
        cur = prev;
    }
    path.reverse();
