1: //! Generic grid A* pathfinding primitives.
2: //!
3: //! [`astar_bool_grid`] takes a `&[bool]` blocking mask and finds a
4: //! 4-connected path between two cells. Manhattan heuristic, uniform cost
5: //! per step. Returned path excludes the start cell and includes the goal,
6: //! in `(col, row)` pairs. Empty `Vec` when start == goal. `None` when
7: //! unreachable.
8: //!
9: //! Game-side grid pathfinders (tile floors with per-tile blocking rules,
10: //! ACL doors, etc.) live in `void_sim::pathfind` and reuse this
11: //! primitive when the tile source can be flattened to a bool grid.
12: 
13: use std::cmp::Reverse;
14: use std::collections::{BinaryHeap, HashMap, HashSet};
15: 
16: /// A* open set: a min-heap keyed on `(f_score, g_score, (col, row))`.
17: /// `Reverse` turns `BinaryHeap`'s max-heap into the min-heap A* wants,
18: /// and `g_score` breaks f-score ties toward the deeper node.
19: type OpenSet = BinaryHeap<Reverse<(u32, u32, (i32, i32))>>;
20: 
21: /// A caller-supplied tile-blocking source. Lets `astar_grid` run over
22: /// any game-side tile representation (station floor, ship exterior,
23: /// etc.) without engine dragging in game types. Out-of-bounds cells
24: /// should return `true` from `blocks`.
25: pub trait TileSource {
26:     /// Grid dimensions in `(width, height)` tile counts.
27:     fn dims(&self) -> (u32, u32);
28:     /// True if `(c, r)` is impassable. Return `true` for out-of-bounds.
29:     fn blocks(&self, c: i32, r: i32) -> bool;
30: }
31: 
32: /// A* on any [`TileSource`]. Same rules as [`astar_bool_grid`] —
33: /// 4-connected, Manhattan heuristic, uniform cost, excludes start,
34: /// includes goal. `extra_blocked` layers extra impassable cells on top
35: /// (used to reject e.g. occupied dock pads that the tile source itself
36: /// would call walkable).
37: pub fn astar_tile_grid<T: TileSource>(
38:     src: &T,
39:     start: (i32, i32),
40:     goal:  (i32, i32),
41:     extra_blocked: &HashSet<(i32, i32)>,
42: ) -> Option<Vec<(u16, u16)>> {
43:     if start == goal { return Some(Vec::new()); }
44:     if src.blocks(goal.0, goal.1) { return None; }
45:     let (w, h) = src.dims();
46:     let heur = |p: (i32, i32)| -> u32 {
47:         (p.0 - goal.0).unsigned_abs() + (p.1 - goal.1).unsigned_abs()
48:     };
49:     let mut open: OpenSet = BinaryHeap::new();
50:     let mut g_score: HashMap<(i32, i32), u32> = HashMap::new();
51:     let mut came_from: HashMap<(i32, i32), (i32, i32)> = HashMap::new();
52:     let mut closed: HashSet<(i32, i32)> = HashSet::new();
53:     open.push(Reverse((heur(start), 0, start)));
54:     g_score.insert(start, 0);
55:     let cap = (w as usize).saturating_mul(h as usize).max(1);
56:     let mut expanded = 0usize;
57:     while let Some(Reverse((_f, g, cur))) = open.pop() {
58:         if cur == goal { return Some(reconstruct(&came_from, cur)); }
59:         if !closed.insert(cur) { continue; }
60:         expanded += 1;
61:         if expanded > cap { return None; }
62:         for (dx, dy) in [(0i32, 1i32), (0, -1), (1, 0), (-1, 0)] {
