133: fn reconstruct(
134:     came_from: &HashMap<(i32, i32), (i32, i32)>,
135:     mut cur: (i32, i32),
136: ) -> Vec<(u16, u16)> {
137:     let mut path = Vec::new();
138:     while let Some(&prev) = came_from.get(&cur) {
139:         path.push((cur.0 as u16, cur.1 as u16));
140:         cur = prev;
141:     }
142:     path.reverse();
143:     path
