1: //! Movement integration: advance every moving entity by its velocity.
2: 
3: use crate::entity::EntityId;
4: use crate::world::World;
5: use crate::{Frozen, Position, Velocity};
6: 
7: /// Step every entity that has both a Position and a Velocity.
8: ///
9: /// Frozen entities keep their Velocity but must not move, so this collects the
10: /// frozen set first and skips it — the ECS has no way to express "has A and B
11: /// but NOT C", so the filter is done by hand, here.
12: pub fn step(world: &mut World, dt: f64) {
13:     let frozen: Vec<EntityId> = world.iter::<Frozen>().map(|(id, _)| id).collect();
14:     let moves: Vec<(EntityId, f64, f64)> = world
15:         .iter2::<Position, Velocity>()
16:         .filter(|(id, _, _)| !frozen.contains(id))
17:         .map(|(id, _, v)| (id, v.dx * dt, v.dy * dt))
18:         .collect();
19:     for (id, dx, dy) in moves {
20:         if let Some(p) = world.get_mut::<Position>(id) {
21:             p.x += dx;
22:             p.y += dy;
23:         }
24:     }
25: }

