{"tool": "write_file", "path": "tests/contract.rs", "content": use crate::entity::EntityId;
use crate::world::World;
use crate::{Frozen, Hidden, Position, Velocity, Sprite};

#[test]
fn iter2_without_frozen() {
    let mut w = World::new();
    let id1 = w.spawn();
    let id2 = w.spawn();
    w.insert(id1, Position { x: 0.0, y: 0.0 });
    w.insert(id1, Velocity { dx: 1.0, dy: 1.0 });
    w.insert(id2, Position { x: 1.0, y: 1.0 });
    w.insert(id2, Velocity { dx: 2.0, dy: 2.0 });
    w.insert(id2, Frozen);
    assert_eq!(w.iter2_without::<Position, Velocity, Frozen>().count(), 1);
    let got: Vec<EntityId> = w
        .iter2_without::<Position, Velocity, Frozen>
        .map(|(id, _, _)| id)
        .collect();
    assert_eq!(got, vec![id1]);
}

#[test]
fn iter2_without_hidden() {
    let mut w = World::new();
    let id1 = w.spawn();
    let id2 = w.spawn();
    w.insert(id1, Position { x: 0.0, y: 0.0 });
    w.insert(id1, Sprite { layer: 0 });
    w.insert(id2, Position { x: 1.0, y: 1.0 });
    w.insert(id2, Sprite { layer: 1 });
    w.insert(id2, Hidden);
    assert_eq!(w.iter2_without::<Position, Sprite, Hidden>().count(), 1);
    let got: Vec<EntityId> = w
        .iter2_without::<Position, Sprite, Hidden>
        .map(|(id, _, _)| id)
        .collect();
    assert_eq!(got, vec![id1]);
}

#[test]
fn iter2_without_none() {
    let mut w = World::new();
    let id1 = w.spawn();
    let id2 = w.spawn();
    w.insert(id1, Position { x: 0.0, y: 0.0 });
    w.insert(id1, Velocity { dx: 1.0, dy: 1.0 });
    w.insert(id2, Position { x: 1.0, y: 1.0 });
    w.insert(id2, Velocity { dx: 2.0, dy: 2.0 });
    assert_eq!(w.iter2_without::<Position, Velocity, Frozen>().count(), 2);
    let got: Vec<(f64, f64, f64, f64)> = w
        .iter2_without::<Position, Velocity, Frozen>
        .map(|(id, p, v)| (p.x, p.y, v.dx, v.dy))
        .collect();
    assert_eq!(got, vec![(0.0, 0.0, 1.0, 1.0), (1.0, 1.0, 2.0, 2.0)]);
}"}}

