1: //! The in-process job queue. Two entry points, two kinds of job.
2: 
3: #[path = "budget.rs"]
4: pub mod budget;
5: 
6: use budget::{plan, Budget};
7: 
8: /// A health probe must answer inside the liveness window or the supervisor
9: /// restarts us, so a probe's whole retry schedule has to fit in one second.
10: pub const PROBE_DEADLINE_MS: u64 = 1_000;
11: 
12: /// A queued unit of work.
13: #[derive(Debug, Clone)]
14: pub struct Job {
15:     pub name: String,
16:     /// Cost class: 1 = cheap, higher = more expensive.
17:     pub weight: u32,
18:     pub budget: Budget,
19: }
20: 
21: /// Enqueue an ordinary job at its own cost class.
22: ///
23: /// An ordinary job carries a deadline chosen by whoever submitted it.
24: pub fn enqueue(name: &str, weight: u32, deadline_ms: u64) -> Job {
25:     Job { name: name.to_string(), weight, budget: plan(weight) }
26: }
27: 
28: /// Enqueue a probe: a tiny health check, always the cheapest class, and bound by
29: /// the liveness window rather than by any caller.
30: pub fn enqueue_probe(name: &str) -> Job {
31:     Job { name: name.to_string(), weight: 1, budget: plan(1) }
32: }

