1: //! Operator-triggered work. Whatever an operator asks for runs at the heaviest
2: //! cost class, because it is always a one-off and never a hot path.
3: 
4: #[path = "queue.rs"]
5: pub mod queue;
6: 
7: use queue::budget::{plan, Budget};
8: 
9: /// The cost class every operator-triggered job runs at.
10: pub const ADMIN_WEIGHT: u32 = 8;
11: 
12: /// An operator sits and watches a rebuild, so it may take as long as five
13: /// minutes before we give up on it.
14: pub const ADMIN_DEADLINE_MS: u64 = 300_000;
15: 
16: /// The budget for an operator-triggered rebuild.
17: pub fn rebuild_budget() -> Budget {
18:     plan(ADMIN_WEIGHT)
19: }

