1: //! Renders a caret line under the offending part of a source line, the way a
2: //! compiler diagnostic does.
3: 
4: #[path = "span.rs"]
5: pub mod span;
6: 
7: use span::{chunk_count, line_span, Span};
8: 
9: /// The source line containing `at`, without its trailing newline.
10: pub fn source_line(text: &str, at: usize) -> &str {
11:     let s = line_span(text, at);
12:     &text[s.start..s.end]
13: }
14: 
15: /// A caret line: spaces up to `at`, then a `^` under the byte at `at`.
16: pub fn caret(text: &str, at: usize) -> String {
17:     let s = line_span(text, at);
18:     let col = at - s.start;
19:     let mut out = " ".repeat(col);
20:     out.push('^');
21:     out
22: }
23: 
24: /// A whole two-line diagnostic body: the source line, then the caret line.
25: pub fn diagnostic(text: &str, at: usize) -> String {
26:     format!("{}\n{}", source_line(text, at), caret(text, at))
27: }
28: 
29: /// The span highlighted by a diagnostic at `at`.
30: pub fn highlight_span(text: &str, at: usize) -> Span {
31:     line_span(text, at)
32: }
33: 
34: /// How many terminal rows a diagnostic for `at` occupies at `width` columns:
35: /// the wrapped source line, plus one row for the caret.
36: pub fn rendered_rows(text: &str, at: usize, width: usize) -> usize {
37:     let s = line_span(text, at);
38:     chunk_count(s.len(), width) + 1
39: }

