1: //! Rendering a duration for the run summary line.
2: 
3: #[path = "split.rs"]
4: pub mod split;
5: 
6: use split::{split, Parts};
7: 
8: /// Render `ms` as `H:MM:SS` for the summary table.
9: ///
10: /// The minute and second fields are two digits so the columns line up; the hour
11: /// field is not padded, because a run can be longer than nine hours and a fixed
12: /// width would truncate it.
13: pub fn render(ms: u64) -> String {
14:     let p = split(ms);
15:     format!("{}:{}:{}", p.hours, pad(p.minutes), pad(p.seconds))
16: }
17: 
18: /// Render `ms` as a short human label, e.g. `2h 5m` or `45s`.
19: ///
20: /// Only the two most significant non-zero units are shown: past an hour the
21: /// seconds are noise, and under a minute the label is just seconds.
22: pub fn label(ms: u64) -> String {
23:     let p = split(ms);
24:     if p.hours > 0 {
25:         format!("{}h {}m", p.hours, p.minutes)
26:     } else if p.minutes > 0 {
27:         format!("{}m {}s", p.minutes, p.seconds)
28:     } else {
29:         format!("{}s", p.seconds)
30:     }
31: }
32: 
33: /// Render a split that was assembled by hand rather than by [`split`], e.g. the
34: /// numbers a user typed into the "remind me in" box.
35: ///
36: /// Hand-assembled parts are not reduced — somebody will type 90 minutes — so
37: /// this carries any overflow up before formatting. Nothing that comes from
38: /// [`split`] needs this: that function reduces its own fields.
39: pub fn render_unreduced(p: Parts) -> String {
40:     let p = carry(p);
41:     format!("{}:{}:{}", p.hours, pad(p.minutes), pad(p.seconds))
42: }
43: 
44: /// Carry any overflowed field up into the next unit.
45: fn carry(p: Parts) -> Parts {
46:     let mut p = p;
47:     if p.seconds >= 60 {
48:         p.minutes += p.seconds / 60;
49:         p.seconds %= 60;
50:     }
51:     if p.minutes >= 60 {
52:         p.hours += p.minutes / 60;
53:         p.minutes %= 60;
54:     }
55:     p
56: }
57: 
58: /// Left-pad a unit to the two-digit column width used by the summary table.
59: fn pad(n: u64) -> String {
60:     if n < 10 {
61:         format!("0{n}")
62:     } else {
63:         format!("{n}")
64:     }
65: }

